 const scrubber=document.createElement('div');scrubber.className='phone-only phone-scrubber';scrubber.innerHTML='<label for="phoneScrub">再生位置</label><input id="phoneScrub" type="range" min="0" max="1" step=".01" value="0" aria-label="再生位置を調整"><output id="phoneScrubTime">0.00秒</output>';layout.before(scrubber);
