 const workspace=document.querySelector('.workspace'),grip=document.createElement('button');grip.className='phone-only phone-workspace-grip';grip.setAttribute('aria-label','プレビューとタイムラインの高さを調整');grip.innerHTML='<span></span>';document.querySelector('.viewer-panel').after(grip);
