 quick.addEventListener('change',e=>{if(e.target.id==='phoneVolume')edit('volume',+e.target.value)});quick.addEventListener('click',e=>{const original=e.target.closest('[data-phone-original]');if(original?.dataset.phoneOriginal){selectItem('audio',original.dataset.phoneOriginal);lastState='';sync();return}if(e.target.id==='phoneMute')edit('mute',e.target.getAttribute('aria-pressed')!=='true')});
 const layers=document.createElement('section');layers.className='phone-only phone-layer-sheet';layers.hidden=true;layers.setAttribute('aria-label','レイヤー編集');body.append(layers);
