 document.addEventListener('pve-phone-tab',()=>{if(!panel)return;const active=document.querySelector('.inspector-tabs .selected')?.dataset.inspectorTab;if(!['adjust','look','detail','motion'].includes(panel))return;const label={cut:'位置・画面',motion:'モーション',adjust:'カラー',look:'ルック'}[active];if(label)$('phoneSheetTitle').textContent=label;});
 const names={motion:'モーション',fx:'エフェクト',analyze:'解析',layers:'レイヤー編集',clips:'クリップ一覧',library:'素材ライブラリ',import:'素材の情報',cut:'クリップ編集',detail:'位置・画面・トランジション',adjust:'カラー',look:'ルック',text:'テキスト',sound:'音声',more:'プロジェクトとツール'};
