 document.addEventListener('keydown',e=>{if(!panel||$('modal').open)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation();dismiss()}if(e.key==='Tab'){
  const surface=panel==='layers'?layers:panel==='clips'?sequenceBar:panel==='library'?document.querySelector('.media-panel'):panel==='more'?menu:document.querySelector('.inspector');
  const items=[close,...surface.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);const i=items.indexOf(document.activeElement);e.preventDefault();items[(i+(e.shiftKey?-1:1)+items.length)%items.length]?.focus();
 }},true);
 $('phoneMove').onclick=null;
 $('phoneLayers').textContent='レイヤー';$('phoneLayers').setAttribute('data-phone-panel','layers');$('phoneLayers').removeAttribute('aria-pressed');$('phoneLayers').onclick=null;
 function update(){const phone=phoneLayout({width:innerWidth,height:innerHeight,coarse:coarse.matches,iphone:/iPhone|iPod/.test(navigator.userAgent)});const next=phone?'phone':'desktop';if(body.dataset.ui===next)return;dismiss();body.dataset.ui=next;if(phone&&$('toast').textContent.includes('Macエンジンに接続できません')){$('toast').textContent='';$('toast').classList.remove('show')}body.classList.remove('phone-moving');refresh();sync();resizePanes()}
